namespace sv_ceb61904fbcb49979b9b161648e020a7.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];
    private readonly Lock _lock = new();
    private static readonly string[] SampleMessages =
    [
        "Your order has shipped!",
        "New comment on your post",
        "Password changed successfully",
        "Welcome to the platform!",
        "You have a new follower",
        "Payment received",
        "Scheduled maintenance tonight",
        "New feature available: Dark Mode",
        "Your report is ready to download",
        "Team meeting in 15 minutes",
    ];

    public NotificationService()
    {
        // Seed initial notifications
        var now = DateTime.UtcNow;
        for (var i = 0; i < 3; i++)
        {
            _notifications.Add(new Notification(
                _nextId++,
                SampleMessages[i],
                now.AddMinutes(-(3 - i))));
        }
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns notifications added after the given ID (for polling).
    /// Randomly adds a new notification ~50% of the time to simulate activity.
    /// </summary>
    public Task<List<Notification>> GetNewNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            if (Random.Shared.Next(2) == 0)
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > lastId).ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private int lastSeenId;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch when state was persisted from prerender
        notifications ??= await NotificationService.GetNotificationsAsync();
        lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(5000, token).ConfigureAwait(false);

            var newItems = await NotificationService.GetNewNotificationsSinceAsync(lastSeenId);
            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications!.AddRange(newItems);
                    lastSeenId = newItems.Max(n => n.Id);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

