@page "/notifications"
@rendermode InteractiveServer
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private int lastSeenId;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch when state was persisted from prerender
        notifications ??= await NotificationService.GetNotificationsAsync();
        lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(5000, token).ConfigureAwait(false);

            var newItems = await NotificationService.GetNewNotificationsSinceAsync(lastSeenId);
            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications!.AddRange(newItems);
                    lastSeenId = newItems.Max(n => n.Id);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

